import type { NextConfig } from "next";

import { legacyRedirects } from "./lib/redirects/legacy";

const sanityProjectId = process.env.NEXT_PUBLIC_SANITY_PROJECT_ID

const nextConfig: NextConfig = {
  // Old kurifturesorts.com paths (generated by the content migration).
  async redirects() {
    return legacyRedirects.map(({ source, destination }) => ({ source, destination, permanent: true }))
  },
  images: {
    // AVIF first (smaller at the same quality), WebP for browsers without it.
    formats: ["image/avif", "image/webp"],
    // Only this project's Sanity image CDN. `search` is left out on purpose:
    // Sanity image URLs carry transform params (?w=…&auto=format), and the
    // `new URL()` form would only match URLs with no query string.
    remotePatterns: sanityProjectId
      ? [{ protocol: "https", hostname: "cdn.sanity.io", pathname: `/images/${sanityProjectId}/**` }]
      : [],
  },
  experimental: {
    agentFeedback: true,
  },
  cacheComponents: true,
  partialPrefetching: true,
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
};

export default nextConfig;
